exercises.solution:
def gini(labels):
    p = sum(labels) / len(labels)
    return 1 - p * p - (1 - p) * (1 - p)

def best_split(rows):
    best = None
    for cut in sorted({row[0] for row in rows})[:-1]:
        left = [label for x, label in rows if x <= cut]
        right = [label for x, label in rows if x > cut]
        score = (len(left) * gini(left) + len(right) * gini(right)) / len(rows)
        if best is None or score < best[1]:
            best = (cut, score)
    return best

rows = [(1, 0), (2, 0), (3, 0), (8, 1), (9, 1), (10, 1)]
cut, score = best_split(rows)
print(cut, round(score, 3))
